// The Fishing view: how much food is in Cobscook Bay in each two-month season.
//
// Every number is the whole amount in the bay before anyone fishes: no cutoffs and no fishing
// method yet. Pure functions first (the tests run them in Node), then createFishing(), which wires
// the controls in the browser. Numbers come from data/fishing.js (generated by
// tools/fishing_model.py); words, colors and species notes from data/fishing-notes.js.
//
// The view has a season picker with every species ranked for that season, then a table of every
// season. "Show" switches between calories and pounds.

import { SEASONS, SPECIES, ADULT_KCAL_YEAR, HERRING_CATCH } from "../data/fishing.js";
import {
  FISH_PAGE, SPECIES_COLORS, OTHER_COLOR, MEASURES, CONFIDENCE, PROFILES, HERRING_METHODS, HERRING_CATCH_NOTE,
  METHOD, FISH_NOTES, SEAWEED, FISH_SOURCES,
} from "../data/fishing-notes.js";
import { esc } from "./geo.js";

export const DEFAULT_STATE = { measure: "kcal" };
const STORE = "prep-lt-fish";
const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

// ---------- numbers ----------

export const seasonOfDate = (d = new Date()) => Math.floor(d.getMonth() / 2);

// A species has a count if any season has a number. null means "not counted".
export const counted = (sp) => sp.lb.some((v) => v !== null);
export const valueOf = (sp, measure, b) => (measure === "lb" ? sp.lb[b] : sp.kcal[b]);

export function seasonTotal(list, measure, b) {
  return list.reduce((sum, sp) => sum + (valueOf(sp, measure, b) || 0), 0);
}

// Active adults the calories would feed for a year, if every animal were caught.
export const adultsFed = (kcal) => kcal / ADULT_KCAL_YEAR;
// The same, as words: to the nearest 10, as in the doc ("1,960").
export const fedText = (kcal) => commas(Math.round(adultsFed(kcal) / 10) * 10);

// That season's species with a number above zero, biggest first, each with its share (0–100).
export function seasonRanking(list, measure, b) {
  const items = list.map((sp) => ({ sp, value: valueOf(sp, measure, b) })).filter((x) => x.value > 0);
  const total = items.reduce((s, x) => s + x.value, 0);
  return items.map((x) => ({ ...x, share: total ? (100 * x.value) / total : 0 })).sort((a, b2) => b2.value - a.value);
}

// Every species for the season: ranked ones first, then none counted, not counted that season,
// and no count at all.
export function seasonRows(list, measure, b) {
  const ranked = seasonRanking(list, measure, b).map((x) => ({ ...x, status: "ranked" }));
  const rest = (status, test) => list.filter(test).map((sp) => ({ sp, value: valueOf(sp, measure, b), share: 0, status }));
  return [
    ...ranked,
    ...rest("none", (sp) => sp.lb[b] === 0),
    ...rest("season", (sp) => sp.lb[b] === null && counted(sp)),
    ...rest("nocount", (sp) => !counted(sp)),
  ];
}

// "Herring 72%, mackerel 14%, …, the rest under 1%"
export function rankingText(list, b) {
  const ranked = seasonRanking(list, "kcal", b);
  const big = ranked.filter((x) => x.share >= 1).map((x) => `${x.sp.short} ${Math.round(x.share)}%`);
  if (ranked.length > big.length) big.push("the rest under 1%");
  const text = big.join(", ");
  return text.charAt(0).toUpperCase() + text.slice(1);
}

// The biggest few species as ring slices, the rest folded into "Other".
export function donutSlices(shares, top = 4) {
  const slices = shares.slice(0, top).map(({ sp, value, share }) => ({
    id: sp.id, name: sp.name, color: SPECIES_COLORS[sp.id] || OTHER_COLOR, value, share,
  }));
  const rest = shares.slice(top);
  if (rest.length) {
    slices.push({
      id: "other", name: `Other (${rest.length})`, color: OTHER_COLOR,
      value: rest.reduce((s, x) => s + x.value, 0), share: rest.reduce((s, x) => s + x.share, 0),
    });
  }
  return slices;
}

// The 1947–58 herring record as table rows (two years a row), its average and its months.
export function herringCatch(data = HERRING_CATCH) {
  const half = Math.ceil(data.years.length / 2);
  const rows = data.years.slice(0, half).map(([y, lb], i) => {
    const other = data.years[i + half];
    return [String(y), commas(lb), other ? String(other[0]) : "", other ? commas(other[1]) : ""];
  });
  const average = data.years.reduce((s, [, lb]) => s + lb, 0) / data.years.length;
  const months = data.monthPct.map((v, i) => [MONTHS[i], v]).filter(([, v]) => v >= 0.5).map(([m, v]) => `${m} ${v}%`).join(", ");
  return { rows, average, months };
}

// ---------- words for numbers ----------

// Two significant figures, with commas: 21,250 -> 21,000.
export function round2(n) {
  if (!n) return 0;
  if (Math.abs(n) < 100) return Math.round(n);
  const p = 10 ** (Math.floor(Math.log10(Math.abs(n))) - 1);
  return Math.round(n / p) * p;
}
export const commas = (n) => Math.round(n).toLocaleString("en-US");
export const pct = (x) => (x > 0 && x < 0.5 ? "<1%" : `${Math.round(x)}%`);

// Calories in millions, as in the table: 1,540 · 7.4 · <0.1 · 0 · ? (not counted).
export function millions(n) {
  if (n === null || n === undefined) return "?";
  if (n === 0) return "0";
  const m = n / 1e6;
  if (m < 0.05) return "<0.1";
  return m < 10 ? m.toFixed(1) : commas(m);
}

// Pounds in thousands, as in the table: 3,580 · 2 · <1 · 0 · ?.
export function thousands(n) {
  if (n === null || n === undefined) return "?";
  if (n === 0) return "0";
  return n < 500 ? "<1" : commas(n / 1e3);
}

// For sentences: "2.1 billion calories", "600 million calories".
export function caloriesText(n) {
  if (n >= 1e9) return `${(round2(n) / 1e9).toLocaleString("en-US")} billion calories`;
  if (n >= 1e6) return `${(round2(n) / 1e6).toLocaleString("en-US")} million calories`;
  return `${commas(round2(n))} calories`;
}

// For one species: "3,580,000 lb", "260 lb".
export function poundsText(n) {
  if (n >= 1000) return `${commas(Math.round(n / 1000) * 1000)} lb`;
  return `${commas(round2(n))} lb`;
}

const weightWord = (sp) => (sp.weight === "meat" ? "meat" : "live weight");

// "60% of live weight, 717 calories a pound of meat"
export function meatText(sp, profile = PROFILES[sp.id] || {}) {
  const cal = `${commas(sp.kcalPerLb)} calories a pound of meat`;
  if (sp.weight === "meat") return `Meat only, ${cal}`;
  if (sp.meatShare) return `${Math.round(sp.meatShare * 100)}% of live weight, ${cal}`;
  return profile.yield ? `${profile.yield}, ${cal}` : cal;
}

// ---------- drawing (HTML strings) ----------

const confChip = (sp) => `<span class="ltf-conf ltf-conf-${sp.confidence}" title="${esc(`How sure: ${sp.confidence} of 5. ${CONFIDENCE[sp.confidence]}`)}">${sp.confidence}</span>`;
const swatch = (sp) => `<span class="ltf-swatch" style="background:${esc(SPECIES_COLORS[sp.id] || OTHER_COLOR)}"></span>`;

function profileHtml(sp, b) {
  const p = PROFILES[sp.id] || {};
  const has = sp.lb[b] !== null;
  const rows = [
    has ? ["Calories this season", sp.kcal[b] ? `${millions(sp.kcal[b])} million` : "None counted"] : null,
    has ? ["Pounds this season", sp.lb[b] ? `${poundsText(sp.lb[b])} (${weightWord(sp)})` : "None counted"] : null,
    ["Meat", meatText(sp, p)],
    ["Where the number comes from", sp.source],
    ["How sure", `${sp.confidence} of 5: ${CONFIDENCE[sp.confidence]}`],
    ["Best season", p.best], ["Size", p.size], ["Gear", p.gear], ["Rules today", p.rules], ["Notes", p.safety],
  ].filter((r) => r && r[1]);
  return `<dl class="ltf-profile">${rows.map(([k, v]) => `<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join("")}</dl>`;
}

const STATUS_TEXT = { none: "none counted", season: "not counted this season", nocount: "no count yet" };

export function drawSeason(state, season, list = SPECIES, seasons = SEASONS) {
  const s = seasons[season];
  const kcal = state.measure === "lb" ? "lb" : "kcal";
  const tabs = seasons.map((x, b) => `<button type="button" class="ltf-stab" data-season="${b}" data-local aria-pressed="${b === season}">${esc(x.label)}</button>`).join("");
  const total = seasonTotal(list, "kcal", season);
  const top = seasonRanking(list, "kcal", season)[0];
  const rows = seasonRows(list, kcal, season);
  const max = Math.max(...rows.map((x) => x.value || 0), 1);

  const items = rows.map((x) => {
    const width = x.status === "ranked" ? (100 * x.value) / max : 0;
    let val;
    if (x.status !== "ranked") val = esc(STATUS_TEXT[x.status]);
    else if (kcal === "kcal") val = `${esc(millions(x.value))} million cal · <b>${esc(pct(x.share))}</b>`;
    else val = esc(poundsText(x.value)) + (x.sp.weight === "meat" ? " of meat" : "");
    return `
      <li>
        <details class="ltf-row${x.status === "ranked" ? "" : " is-blank"}" data-id="${esc(x.sp.id)}">
          <summary>
            <span class="ltf-row-name">${swatch(x.sp)}${esc(x.sp.name)} ${confChip(x.sp)}</span>
            <span class="ltf-row-bar"><span style="width:${width.toFixed(1)}%;background:${esc(SPECIES_COLORS[x.sp.id] || OTHER_COLOR)}"></span></span>
            <span class="ltf-row-val">${val}</span>
          </summary>
          ${profileHtml(x.sp, season)}
        </details>
      </li>`;
  }).join("");

  return `
    <div class="ltf-stabs" role="group" aria-label="Season">${tabs}</div>
    <h3 class="sub-title ltf-detail-title">${esc(s.long)}</h3>
    <p class="ltf-detail-lead">About <b>${esc(caloriesText(total))}</b> in the bay: a year's food for about <b>${esc(fedText(total))} active adults</b>, if every animal were caught.${top ? ` Biggest share: ${esc(top.sp.name)}, <b>${esc(pct(top.share))}</b>.` : ""}</p>
    <h4 class="ltf-h4">${kcal === "kcal" ? "Every species, largest share of the calories first" : "Every species, most pounds first"}</h4>
    <p class="ltf-hint">The number in the box is how sure the estimate is, from 1 (could be off more than 10 times) to 5 (likely within 25%). Tap a species for where its number comes from.</p>
    <ol class="ltf-bars">${items}</ol>`;
}

export function drawTable(state, season, list = SPECIES, seasons = SEASONS) {
  const lb = state.measure === "lb";
  const fmt = lb ? thousands : millions;
  const heads = seasons.map((s, b) => `<th scope="col"${b === season ? ' class="is-on"' : ""}><button type="button" data-season="${b}" aria-pressed="${b === season}">${esc(s.label.replace("–", "–​"))}</button></th>`).join("");
  const cell = (v, b) => `<td class="${b === season ? "is-on" : ""}${v === null ? " is-unknown" : ""}">${esc(fmt(v))}</td>`;
  const rows = list.map((sp) => {
    const vals = lb ? sp.lb : sp.kcal;
    const name = lb && sp.weight === "meat" ? `${sp.name} (meat)` : sp.name;
    return `<tr><th scope="row">${swatch(sp)}${esc(name)}</th>${vals.map(cell).join("")}<td class="ltf-tbl-conf">${confChip(sp)}</td></tr>`;
  }).join("");
  const foot = lb ? "" : `
        <tfoot>
          <tr><th scope="row">Total</th>${seasons.map((_, b) => cell(seasonTotal(list, "kcal", b), b)).join("")}<td></td></tr>
          <tr><th scope="row">Active adults fed a year, if all were caught</th>${seasons.map((_, b) => `<td class="${b === season ? "is-on" : ""}">${esc(fedText(seasonTotal(list, "kcal", b)))}</td>`).join("")}<td></td></tr>
        </tfoot>`;
  return `
    <div class="table-scroll ltf-tbl-wrap">
      <table class="ltf-tbl">
        <caption>${lb ? "Pounds in the bay, in thousands (live weight; scallops are meat). Pounds aren't added up, since meat and shell weigh so differently." : "Calories in the bay, in millions."} ? = not counted. The last column is how sure, 1 to 5.</caption>
        <thead><tr><th scope="col">Species</th>${heads}<th scope="col" class="ltf-tbl-conf">Sure</th></tr></thead>
        <tbody>${rows}</tbody>${foot}
      </table>
    </div>`;
}

function herringHtml() {
  const hc = herringCatch();
  return `
      <details class="ltm-notes">
        <summary>Herring: three ways to measure it</summary>
        <p>${esc(HERRING_METHODS.lead)}</p>
        <div class="table-scroll"><table class="data ltf-table">
          <thead><tr><th scope="col">Method</th><th scope="col">Herring in the bay</th><th scope="col">How it was made</th></tr></thead>
          <tbody>${HERRING_METHODS.rows.map((r) => `<tr><th scope="row">${esc(r[0])}</th><td>${esc(r[1])}</td><td>${esc(r[2])}</td></tr>`).join("")}</tbody>
        </table></div>
        <p class="ltf-hint">${esc(HERRING_METHODS.after)}</p>
      </details>
      <details class="ltm-notes">
        <summary>Herring caught in Cobscook, 1947–58</summary>
        <div class="table-scroll"><table class="data ltf-table ltf-herring">
          <thead><tr><th scope="col">Year</th><th scope="col">Pounds</th><th scope="col">Year</th><th scope="col">Pounds</th></tr></thead>
          <tbody>${hc.rows.map((r) => `<tr>${r.map((c) => `<td>${esc(c)}</td>`).join("")}</tr>`).join("")}</tbody>
        </table></div>
        <p class="ltf-hint">Average ${esc(commas(hc.average))} lb a year. By month: ${esc(hc.months)} of the catch. ${esc(HERRING_CATCH_NOTE)}</p>
      </details>`;
}

// The static page: heading, controls, empty season and table areas, notes.
export function renderFishing(page = FISH_PAGE) {
  const seg = Object.entries(MEASURES).map(([v, m], i) => `
        <label class="ltm-seg-item"><input type="radio" name="ltf-measure" value="${esc(v)}"${i === 0 ? " checked" : ""}><span>${esc(m.label)}</span></label>`).join("");
  const conf = Object.keys(CONFIDENCE).sort((a, b) => b - a).map((k) => `<li><span class="ltf-conf ltf-conf-${esc(k)}">${esc(k)}</span> ${esc(CONFIDENCE[k])}</li>`).join("");
  return `
    <section class="ltf" aria-labelledby="ltf-heading">
      <h2 id="ltf-heading" class="section-title">${esc(page.heading)}</h2>
      <p class="muted ltf-intro">${esc(page.intro)} <span class="ltf-draft">${esc(page.draft)}</span></p>

      <div class="ltf-controls">
        <div class="ltm-group" role="radiogroup" aria-labelledby="ltf-measure-label">
          <span id="ltf-measure-label" class="ltm-label">Show</span>
          <div class="ltm-seg ltf-seg-2">${seg}</div>
        </div>
      </div>

      <div class="ltf-detail" data-detail></div>
      <h3 class="sub-title ltf-detail-title">Every season at a glance</h3>
      <p class="ltf-hint">For species that stay all year, like periwinkles, clams and scallops, each season shows the same animals, so don't add the seasons together.</p>
      <div class="ltf-chart" data-table></div>

      <details class="ltm-notes" open>
        <summary>Keep in mind</summary>
        <ul>${FISH_NOTES.map((n) => `<li>${esc(n)}</li>`).join("")}</ul>
      </details>${herringHtml()}
      <details class="ltm-notes">
        <summary>Seaweed (not counted above)</summary>
        <div class="table-scroll"><table class="data ltf-table">
          <thead><tr><th scope="col">Seaweed</th><th scope="col">Best time to pick</th><th scope="col">Use</th></tr></thead>
          <tbody>${SEAWEED.map((r) => `<tr>${r.map((c, i) => (i ? `<td>${esc(c)}</td>` : `<th scope="row">${esc(c)}</th>`)).join("")}</tr>`).join("")}</tbody>
        </table></div>
        <p class="ltf-hint">Cut the fronds and leave the base attached so it grows back. Don't pick near sewage outfalls.</p>
      </details>
      <details class="ltm-notes">
        <summary>How these numbers were made</summary>
        <p class="ltf-hint">How sure each number is:</p>
        <ul class="ltf-conf-list">${conf}</ul>
        <ol>${METHOD.map((n) => `<li>${esc(n)}</li>`).join("")}</ol>
      </details>
      <details class="ltm-notes">
        <summary>Sources</summary>
        <ul>${FISH_SOURCES.map(([t, u]) => `<li><a href="${esc(u)}" target="_blank" rel="noopener">${esc(t)}</a></li>`).join("")}</ul>
      </details>
    </section>`;
}

// ---------- browser ----------

function readState() {
  try {
    const s = JSON.parse(localStorage.getItem(STORE) || "{}");
    return { measure: MEASURES[s.measure] ? s.measure : DEFAULT_STATE.measure };
  } catch { return { ...DEFAULT_STATE }; }
}
function saveState(state) {
  try { localStorage.setItem(STORE, JSON.stringify({ measure: state.measure })); } catch { /* private mode */ }
}

export function createFishing(panel) {
  const $ = (sel) => panel.querySelector(sel);
  const state = readState();
  let season = seasonOfDate();
  const detail = $("[data-detail]"), table = $("[data-table]");

  for (const input of panel.querySelectorAll('input[name="ltf-measure"]')) input.checked = input.value === state.measure;

  function draw() {
    const open = new Set([...detail.querySelectorAll("details[open][data-id]")].map((d) => d.dataset.id));
    detail.innerHTML = drawSeason(state, season);
    table.innerHTML = drawTable(state, season);
    for (const d of detail.querySelectorAll("details[data-id]")) if (open.has(d.dataset.id)) d.open = true;
  }

  function onChange(e) {
    if (e.target.name !== "ltf-measure") return;
    state.measure = e.target.value;
    saveState(state);
    draw();
  }
  function onClick(e) {
    const btn = e.target.closest("[data-season]");
    if (!btn || !panel.contains(btn)) return;
    season = Number(btn.dataset.season);
    draw();
    if (!btn.hasAttribute("data-local")) {
      detail.scrollIntoView({ behavior: "smooth", block: "start" });
    } else {
      detail.querySelector(`[data-season="${season}"]`)?.focus();
    }
  }

  panel.addEventListener("change", onChange);
  panel.addEventListener("click", onClick);
  draw();

  return {
    destroy() {
      panel.removeEventListener("change", onChange);
      panel.removeEventListener("click", onClick);
    },
  };
}
